const coords=[[11.4,17],[37.1,17],[62.9,17],[88.6,17],[88.6,39],[88.6,61],[88.6,83],[62.9,83],[37.1,83],[11.4,83],[11.4,61],[11.4,39]];
function renderTiles(position=0){document.getElementById('tiles').innerHTML=coords.map(([x,y],n)=>`<div class="tile ${n%2?'i':'p'} ${[3,7,11].includes(n)?'b':''} ${n===position?'current':''} ${n<position?'done':''}" style="left:${x}%;top:${y}%" aria-label="Casa ${n+1}${n===position?', você está aqui':''}"><span class="tile-symbol">${n===position?'◆':[3,7,11].includes(n)?'✧':n%2?'✳':'◎'}</span><small>${String(n+1).padStart(2,'0')}</small></div>`).join('')};renderTiles();
const $=id=>document.getElementById(id);
const STORAGE='imunotrilha-v1';
const shuffle=a=>{const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b};
function newState(){const p=shuffle(QUESTIONS.filter(q=>q.type==='p')),i=shuffle(QUESTIONS.filter(q=>q.type==='i'));return {version:1,coins:100,index:0,correct:0,streak:0,bestStreak:0,phase:'ready',deck:Array.from({length:12},(_,n)=>(n%2?i:p)[Math.floor(n/2)].id),orders:{},selected:null,eliminated:[],hintUsed:false,errors:[],reviewed:[],last:null}}
function validState(s){return s&&s.version===1&&Array.isArray(s.deck)&&s.deck.length===12&&new Set(s.deck).size===12&&s.deck.every(id=>QUESTIONS[id])&&Number.isInteger(s.index)&&s.index>=0&&s.index<=12&&Number.isInteger(s.coins)&&s.coins>=0&&Number.isInteger(s.correct)&&s.correct>=0&&s.correct<=12&&Number.isInteger(s.streak)&&s.streak>=0&&s.streak<=12&&Number.isInteger(s.bestStreak)&&s.bestStreak>=0&&s.bestStreak<=12&&['ready','question','feedback','finished'].includes(s.phase)&&Array.isArray(s.errors)&&s.errors.every(id=>QUESTIONS[id])&&Array.isArray(s.reviewed)&&s.reviewed.every(id=>QUESTIONS[id])&&Array.isArray(s.eliminated)&&s.eliminated.every(n=>Number.isInteger(n)&&n>=0&&n<4)&&typeof s.hintUsed==='boolean'&&(s.selected===null||Number.isInteger(s.selected)&&s.selected>=0&&s.selected<4)&&s.orders&&typeof s.orders==='object'&&Object.values(s.orders).every(a=>Array.isArray(a)&&a.length===4&&new Set(a).size===4&&a.every(n=>Number.isInteger(n)&&n>=0&&n<4))&&(s.phase==='finished'||s.index<12)&&(s.phase!=='feedback'||s.last&&typeof s.last.correct==='boolean'&&Number.isFinite(s.last.delta))}
let state;try{const saved=JSON.parse(localStorage.getItem(STORAGE));state=validState(saved)?saved:newState()}catch{state=newState()}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state))}catch{$('save-status').textContent='Progresso disponível apenas nesta sessão'}}
const current=()=>QUESTIONS[state.deck[state.index]];
const sourceLink=q=>`<a href="${REFERENCES[q.source].url}" target="_blank" rel="noopener noreferrer">${REFERENCES[q.source].label} ↗</a>`;
function stats(){const answered=state.index+(state.phase==='feedback'?1:0);$('coins').innerHTML=`${state.coins} <span>moedas</span>`;$('accuracy').innerHTML=`${state.correct} <span>de ${answered} cartas</span>`;$('streak').innerHTML=`${state.streak} <span>acertos seguidos</span>`;$('progress-label').innerHTML=`${answered} <span>/ 12 casas</span>`;$('progress-fill').style.width=`${answered/12*100}%`;$('review-count').textContent=state.errors.filter(id=>!state.reviewed.includes(id)).length;$('card-counter').textContent=state.phase==='finished'?'EXPEDIÇÃO CONCLUÍDA':`CARTA ${String(state.index+1).padStart(2,'0')} / 12`;renderTiles(state.phase==='finished'?12:state.index)}
function focusCard(){const heading=$('card-area').querySelector('h3');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true})}if(matchMedia('(max-width:760px)').matches)$('card-area').scrollIntoView({behavior:'smooth',block:'start'})}
function draw(){if(state.phase!=='ready')return;state.phase='question';state.orders[state.index]=shuffle([0,1,2,3]);save();render();focusCard()}
function selectAnswer(n){if(state.phase!=='question'||!Number.isInteger(n)||n<0||n>3||state.eliminated.includes(n))return;state.selected=n;save();renderQuestion();const btn=$('card-area').querySelector(`[data-option="${n}"]`);btn?.focus({preventScroll:true})}
function hint(){if(state.phase!=='question'||state.hintUsed||state.coins<5)return;const q=current();state.coins-=5;state.hintUsed=true;state.eliminated=shuffle([0,1,2,3].filter(n=>n!==q.answer)).slice(0,2);if(state.eliminated.includes(state.selected))state.selected=null;save();render();$('coin-delta').textContent='−5';$('hint').focus({preventScroll:true})}
function submit(){if(state.phase!=='question'||state.selected===null)return;const q=current(),correct=state.selected===q.answer;let delta=correct?20:-10,combo=0,checkpoint=0;if(correct){state.correct++;state.streak++;state.bestStreak=Math.max(state.bestStreak,state.streak);if(state.streak%3===0){combo=10;delta+=combo}}else{state.streak=0;if(!state.errors.includes(q.id))state.errors.push(q.id)}if([3,7,11].includes(state.index)){checkpoint=10;delta+=checkpoint}const before=state.coins;state.coins=Math.max(0,state.coins+delta);state.last={correct,delta:state.coins-before,combo,checkpoint};state.phase='feedback';save();render();$('coin-delta').textContent=`${state.last.delta>=0?'+':''}${state.last.delta}`;$('feedback').focus({preventScroll:true})}
function next(){if(state.phase!=='feedback')return;state.index++;state.selected=null;state.eliminated=[];state.hintUsed=false;state.last=null;state.phase=state.index>=12||state.coins===0?'finished':'question';if(state.phase==='question')state.orders[state.index]=shuffle([0,1,2,3]);save();render();focusCard()}
function renderQuestion(){const q=current(),done=state.phase==='feedback';const order=state.orders[state.index]||[0,1,2,3];$('card-area').innerHTML=`<div class="question-type"><span class="type-badge ${q.type}">${q.type==='p'?'PARASITOLOGIA':'IMUNOLOGIA'}</span><span>◈ +20 / −10</span></div><h3 class="question-title">${q.question}</h3><p class="question-topic">${q.topic} · Escolha uma resposta</p><div class="options" role="group" aria-label="Alternativas">${order.map((n,i)=>`<button class="option ${state.selected===n?'selected':''} ${state.eliminated.includes(n)?'eliminated':''} ${done&&n===q.answer?'correct':''} ${done&&state.selected===n&&n!==q.answer?'wrong':''}" data-option="${n}" aria-pressed="${state.selected===n}" ${done||state.eliminated.includes(n)?'disabled':''}><span class="letter">${done&&n===q.answer?'✓':done&&state.selected===n?'×':'ABCD'[i]}</span><span>${q.options[n]}${done&&n===q.answer?'<span class="sr-only"> — Resposta correta</span>':''}${done&&n===state.selected&&n!==q.answer?'<span class="sr-only"> — Sua resposta, incorreta</span>':''}</span></button>`).join('')}</div>${done?`<div class="feedback ${state.last.correct?'':'incorrect'}" id="feedback" tabindex="-1" role="status"><strong>${state.last.correct?'Boa jogada!':'Uma nova chance de aprender.'}</strong><p>${q.explanation}</p>${sourceLink(q)}<div class="reward-breakdown">${state.last.correct?'+20 pelo acerto':'−10 pela resposta incorreta'}${state.last.combo?' · +10 pela sequência':''}${state.last.checkpoint?' · +10 pela casa bônus':''}</div></div><div class="question-actions"><button class="primary" id="next">${state.index===11||state.coins===0?'Ver resultado':'Próxima carta'} <span>→</span></button></div>`:`<div class="question-actions"><button class="primary" id="confirm" ${state.selected===null?'disabled':''}>Confirmar resposta <span>→</span></button><button class="hint" id="hint" ${state.hintUsed||state.coins<5?'disabled':''}>${state.hintUsed?'Dica usada · duas alternativas eliminadas':'✧ Usar dica · −5 moedas'}</button></div>`}`;$('card-area').querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>selectAnswer(Number(b.dataset.option)));if(done)$('next').onclick=next;else{$('confirm').onclick=submit;$('hint').onclick=hint}}
const initialCard=$('card-area').innerHTML;
function render(){stats();$('coin-delta').textContent='';if(state.phase==='ready'){$('card-area').innerHTML=initialCard;$('draw').onclick=draw}else if(state.phase==='finished'){const total=state.index;$('card-area').innerHTML=`<div class="summary"><div class="summary-symbol">${state.coins===0?'✧':'⚑'}</div><div class="eyebrow" style="justify-content:center">${state.coins===0?'MOEDAS ESGOTADAS':'EXPEDIÇÃO CONCLUÍDA'}</div><h3>${state.correct>=10?'Conhecimento de sobra!':state.correct>=6?'Uma boa jornada!':'Toda descoberta conta.'}</h3><p>${state.correct} acertos em ${total} cartas.<br>Melhor sequência: ${state.bestStreak} acertos.</p><div class="summary-score">${state.coins}<small>moedas ao final da expedição</small></div><p>${state.errors.length?'Revise os conceitos que faltaram antes da próxima aventura.':'Você concluiu sem erros. Que tal explorar novas cartas?'}</p><button class="primary" id="summary-review">Revisar aprendizados →</button><button class="secondary" id="play-again">Jogar novamente</button></div>`;$('summary-review').onclick=review;$('play-again').onclick=reset}else renderQuestion()}
function reset(){state=newState();save();render();$('modal').close();setView('board')}
function modal(title,html){$('modal-title').textContent=title;$('modal-body').innerHTML=html;if(!$('modal').open)$('modal').showModal()}
$('close-modal').onclick=()=>$('modal').close();$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close()}});
$('help').onclick=()=>modal('Como jogar',`<p>Explore 12 casas alternando parasitologia e imunologia. O objetivo é aprender e terminar a expedição com o maior saldo possível.</p><ol><li><b>Comece com 100 moedas.</b> Comprar cartas é grátis. Selecione uma alternativa e confirme.</li><li><b>Acertou? +20 moedas.</b> Errou? −10 moedas. Leia a explicação e avance uma casa em qualquer caso.</li><li><b>Três acertos consecutivos rendem +10.</b> O bônus se repete a cada grupo de três. Um erro interrompe a sequência.</li><li><b>Casas 4, 8 e 12: +10 moedas.</b> Você recebe o bônus ao responder à carta da casa, mesmo se errar.</li><li><b>Precisa de ajuda?</b> Uma dica custa 5 moedas e elimina duas alternativas incorretas, uma vez por carta.</li><li><b>Aprenda com os erros.</b> Revise as cartas sem gastar moedas. A partida acaba após 12 cartas ou quando o saldo chega a zero ao concluir uma resposta.</li></ol><p class="muted">Sem cronômetro e sem dinheiro real. Seu progresso fica salvo apenas neste navegador. Uma nova partida embaralha as cartas e reinicia o saldo e a revisão.</p>`);
$('restart').onclick=()=>{modal('Começar uma nova partida?',`<p>O saldo voltará para 100 moedas. O progresso e a lista de erros desta partida serão reiniciados.</p><button class="primary" id="confirm-reset">Começar nova partida</button><button class="secondary" id="cancel-reset">Continuar a partida atual</button>`);$('confirm-reset').onclick=reset;$('cancel-reset').onclick=()=>$('modal').close()};
function review(){const pending=state.errors.filter(id=>!state.reviewed.includes(id));if(!pending.length){modal('Revisão de aprendizados',`<p>${state.errors.length?'Você revisou todos os erros desta partida.':'Nenhum erro para revisar por enquanto.'}</p><p class="muted">Você também pode explorar todas as cartas e explicações na biblioteca.</p><button class="primary" id="open-library">Explorar biblioteca →</button>`);$('open-library').onclick=()=>{$('modal').close();setView('library')};return}const q=QUESTIONS[pending[0]];modal(`Revisão · ${pending.length} ${pending.length===1?'carta restante':'cartas restantes'}`,`<span class="type-badge ${q.type}">${q.type==='p'?'PARASITOLOGIA':'IMUNOLOGIA'}</span><h3>${q.question}</h3><p class="muted">Tente lembrar a resposta antes de revelá-la.</p><button class="primary" id="reveal">Revelar explicação</button><div id="review-answer" hidden><p><b>${q.options[q.answer]}</b></p><p>${q.explanation}</p>${sourceLink(q)}<button class="primary" id="learned" style="margin-top:20px">Entendi · próxima carta →</button></div>`);$('reveal').onclick=()=>{$('reveal').hidden=true;$('review-answer').hidden=false;$('learned').focus()};$('learned').onclick=()=>{state.reviewed.push(q.id);save();stats();review()}}
$('review').onclick=review;
function library(filter='all'){$('library-grid').innerHTML=QUESTIONS.filter(q=>filter==='all'||q.type===filter).map(q=>`<article class="library-card"><span class="type-badge ${q.type}">${q.type==='p'?'PARASITOLOGIA':'IMUNOLOGIA'}</span><h3>${q.question}</h3><details><summary>Ver resposta e explicação</summary><p><b>${q.options[q.answer]}</b></p><p>${q.explanation}</p>${sourceLink(q)}</details></article>`).join('')}
function setView(view){$('board-view').hidden=view!=='board';$('library-view').hidden=view!=='library';document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});if(view==='library'){const filter=document.querySelector('[data-filter].selected')?.dataset.filter||'all';library(filter)}}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));library(b.dataset.filter)});
$('sources').onclick=()=>modal('Fontes e conteúdo',`<p>24 cartas introdutórias para estudantes de ciências da saúde, com explicações e links para aprofundamento. Conteúdo educacional, sem orientações individuais de diagnóstico ou tratamento.</p><ul>${Object.values(REFERENCES).map(r=>`<li><a href="${r.url}" target="_blank" rel="noopener noreferrer">${r.label} ↗</a></li>`).join('')}</ul><p class="muted">As referências externas estão em inglês. Textos das cartas redigidos em português. Revisão das referências: setembro de 2026.</p>`);
render();save();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}};const snapshot=()=>({moedas:state.coins,casa:Math.min(state.index+1,12),fase:state.phase,acertos:state.correct,pergunta:state.phase==='question'?current().question:null,alternativas:state.phase==='question'?current().options:null});register({name:'consultar_partida',title:'Consultar partida',description:'Consulta saldo, progresso e carta atual sem alterar a partida.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>snapshot()});register({name:'comprar_primeira_carta',title:'Comprar primeira carta',description:'Inicia gratuitamente a partida pronta e mostra a primeira carta.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{if(state.phase!=='ready')throw Error('A partida já foi iniciada.');draw();return snapshot()}});register({name:'responder_carta',title:'Responder carta',description:'Confirma uma alternativa da carta atual e aplica a pontuação da resposta. O índice corresponde à lista de alternativas consultada.',inputSchema:{type:'object',properties:{alternativa:{type:'integer',minimum:0,maximum:3}},required:['alternativa'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Number.isInteger(input.alternativa)||input.alternativa<0||input.alternativa>3||state.phase!=='question'||state.eliminated.includes(input.alternativa))throw Error('Alternativa ou momento inválido.');selectAnswer(input.alternativa);submit();return {...snapshot(),explicacao:current().explanation}}});register({name:'avancar_apos_resposta',title:'Avançar após resposta',description:'Avança da explicação para a próxima carta ou para o resultado final.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{if(state.phase!=='feedback')throw Error('Responda à carta antes de avançar.');next();return snapshot()}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
